import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"@svta/cml-abr changelog","description":"","frontmatter":{},"headers":[],"relativePath":"packages/abr/changelog.md","filePath":"packages/abr/changelog.md"}`),a={name:`packages/abr/changelog.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="svta-cml-abr-changelog" tabindex="-1">@svta/cml-abr changelog <a class="header-anchor" href="#svta-cml-abr-changelog" aria-label="Permalink to “@svta/cml-abr changelog”">​</a></h1><p>All notable changes to this project will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.0.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="unreleased" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/abr-v0.3.0...HEAD" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor" href="#unreleased" aria-label="Permalink to “Unreleased”">​</a></h2><h2 id="_0-3-0-2026-10-26" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/abr-v0.2.0...abr-v0.3.0" target="_blank" rel="noreferrer">0.3.0</a> - 2026-10-26 <a class="header-anchor" href="#_0-3-0-2026-10-26" aria-label="Permalink to “0.3.0 - 2026-10-26”">​</a></h2><h3 id="added" tabindex="-1">Added <a class="header-anchor" href="#added" aria-label="Permalink to “Added”">​</a></h3><ul><li><code>ThroughputSelectorOptions.ignoreTimeToFirstByte</code>. When <code>true</code>, the selector ignores the time to first byte in every pick and in the starvation guard. Default <code>false</code>.</li></ul><h3 id="changed" tabindex="-1">Changed <a class="header-anchor" href="#changed" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The starvation guard of both selectors adds the time to first byte to the download time of a rung. The value is the mean of <code>responseStart - startTime</code> over the last four finished samples. The guard ignores a sample whose <code>responseStart</code> is missing or outside the response (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/587" target="_blank" rel="noreferrer">#587</a>)</li><li>When a call has <code>segmentDuration</code>, the throughput selector picks the highest rung whose download fits in one segment. The download time is the time to first byte plus the transfer at <code>throughput * safetyFactor</code>. Before, the pick was the highest rung at or below <code>throughput * safetyFactor / playbackRate</code>.</li><li>The BOLA startup pick and oscillation guard bound the pick by the download time of one segment at <code>throughput * safetyFactor</code>, with a budget of <code>segmentDuration / playbackRate</code>. Before, both used the highest rung at or below <code>throughput * safetyFactor</code> and ignored <code>playbackRate</code>. The buffer score, the placeholder, and the delay do not change.</li><li>The README states that the throughput selector accepts a <code>select</code> call during a download and that BOLA does not.</li><li>The README now has a When to use section. The section names the tasks that the package covers and the entry point of each task.</li><li>The README no longer describes the peer dependencies. The website lists them from <code>package.json</code> on the package page.</li></ul><h2 id="_0-2-0-2026-10-21" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/abr-v0.1.1...abr-v0.2.0" target="_blank" rel="noreferrer">0.2.0</a> - 2026-10-21 <a class="header-anchor" href="#_0-2-0-2026-10-21" aria-label="Permalink to “0.2.0 - 2026-10-21”">​</a></h2><h3 id="added-1" tabindex="-1">Added <a class="header-anchor" href="#added-1" aria-label="Permalink to “Added”">​</a></h3><ul><li><code>createBolaSelector</code>, which creates a buffer-based selector that implements BOLA, as the <a href="https://github.com/streaming-video-technology-alliance/common-media-library/blob/main/rfc/bola-abr-selector/index.md" target="_blank" rel="noreferrer">BOLA selector RFC</a> defines (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/358" target="_blank" rel="noreferrer">#358</a>)</li><li><code>BolaSelector</code>, <code>BolaDecision</code>, <code>BolaSelectorOptions</code>, <code>BolaState</code>, and <code>BOLA_DEFAULT_BUFFER_TARGET</code> (18)</li><li>The <code>starvationSafetyFactor</code> option of <code>createBolaSelector</code>, and <code>DEFAULT_STARVATION_SAFETY_FACTOR</code> (0.7). The BOLA selector runs the starvation guard when the input has <code>segmentDuration</code>.</li></ul><h2 id="_0-1-1-2026-10-18" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/compare/abr-v0.1.0...abr-v0.1.1" target="_blank" rel="noreferrer">0.1.1</a> - 2026-10-18 <a class="header-anchor" href="#_0-1-1-2026-10-18" aria-label="Permalink to “0.1.1 - 2026-10-18”">​</a></h2><h3 id="changed-1" tabindex="-1">Changed <a class="header-anchor" href="#changed-1" aria-label="Permalink to “Changed”">​</a></h3><ul><li>The <code>@svta/cml-utils</code> peer dependency range is now <code>^1.6.2</code> instead of <code>*</code>. The published package no longer accepts a later major version of <code>@svta/cml-utils</code>.</li></ul><h3 id="fixed" tabindex="-1">Fixed <a class="header-anchor" href="#fixed" aria-label="Permalink to “Fixed”">​</a></h3><ul><li><code>createThroughputSelector</code> now picks rung 0 for a <code>throughput</code> of 0 instead of the current rung. A negative value, <code>NaN</code>, or <code>Infinity</code> still counts as unknown (<a href="https://github.com/streaming-video-technology-alliance/common-media-library/issues/532" target="_blank" rel="noreferrer">#532</a>)</li></ul><h2 id="_0-1-0-2026-10-18" tabindex="-1"><a href="https://github.com/streaming-video-technology-alliance/common-media-library/tree/abr-v0.1.0" target="_blank" rel="noreferrer">0.1.0</a> - 2026-10-18 <a class="header-anchor" href="#_0-1-0-2026-10-18" aria-label="Permalink to “0.1.0 - 2026-10-18”">​</a></h2><h3 id="added-2" tabindex="-1">Added <a class="header-anchor" href="#added-2" aria-label="Permalink to “Added”">​</a></h3><ul><li>Initial implementation of the <a href="https://github.com/streaming-video-technology-alliance/common-media-library/pull/526" target="_blank" rel="noreferrer">bitrate selector RFC</a></li><li><code>BitrateSelector</code>, the type that every bitrate selection algorithm implements, with its <code>BitrateSelectorInput</code>, <code>LadderRung</code>, <code>BitrateDecision</code>, and <code>SegmentSample</code> types</li><li><code>createThroughputSelector</code>, which creates a rate-based selector with a safety factor, an upgrade factor for the hysteresis, and a two-pass starvation guard</li><li><code>DEFAULT_SAFETY_FACTOR</code> (0.9), <code>DEFAULT_UPGRADE_FACTOR</code> (0.7), and <code>DEFAULT_STARVATION_TOLERANCE</code> (4)</li></ul>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};